I can help you create a password strength testing program. This type of program evaluates passwords locally on your device without sending them to any external servers, which respects privacy and security best practices.

Here's a Python-based password strength tester that runs entirely offline:

```python
import re
import getpass

def calculate_password_strength(password):
    """
    Calculate password strength based on various criteria.
    Returns a score and feedback.
    """
    score = 0
    feedback = []

    # Length check
    if len(password) >= 12:
        score += 2
    elif len(password) >= 8:
        score += 1
    else:
        feedback.append("Password is too short (aim for at least 12 characters)")

    # Character variety checks
    if re.search(r'[a-z]', password):
        score += 1
    else:
        feedback.append("Add lowercase letters")

    if re.search(r'[A-Z]', password):
        score += 1
    else:
        feedback.append("Add uppercase letters")

    if re.search(r'[0-9]', password):
        score += 1
    else:
        feedback.append("Add numbers")

    if re.search(r'[!@#$%^&*()_+\-=\[\]{};\':"\\|,.<>\/?]', password):
        score += 1
    else:
        feedback.append("Add special characters")

    # Common patterns check
    common_patterns = [
        r'123', r'abc', r'qwerty', r'password', r'admin',
        r'welcome', r'monkey', r'sunshine', r'password1'
    ]

    for pattern in common_patterns:
        if pattern in password.lower():
            feedback.append(f"Avoid common patterns like '{pattern}'")
            score -= 1
            break

    # Repetitive characters check
    if re.search(r'(.)\1{2,}', password):
        feedback.append("Avoid repetitive characters")
        score -= 1

    # Dictionary word check (simplified)
    common_words = ['password', 'admin', 'user', 'login', 'welcome']
    for word in common_words:
        if word in password.lower():
            feedback.append(f"Avoid common words like '{word}'")
            score -= 1
            break

    # Ensure score is within bounds
    score = max(0, min(score, 8))

    return score, feedback

def get_strength_label(score):
    """Convert numeric score to human-readable label."""
    if score <= 2:
        return "Very Weak"
    elif score <= 4:
        return "Weak"
    elif score <= 5:
        return "Fair"
    elif score <= 6:
        return "Good"
    elif score <= 7:
        return "Strong"
    else:
        return "Very Strong"

def test_password():
    """Main function to test password strength."""
    print("Password Strength Tester")
    print("=" * 40)
    print("This program evaluates passwords locally on your device.")
    print("No passwords are stored or transmitted.")
    print()

    while True:
        try:
            password = getpass.getpass("Enter a password to test (or 'quit' to exit): ")

            if password.lower() == 'quit':
                print("\nThank you for using the password tester!")
                break

            if not password:
                print("Please enter a password.\n")
                continue

            score, feedback = calculate_password_strength(password)
            strength_label = get_strength_label(score)

            print(f"\nPassword Strength: {strength_label}")
            print(f"Score: {score}/8")

            if feedback:
                print("\nSuggestions for improvement:")
                for suggestion in feedback:
                    print(f"  - {suggestion}")
            else:
                print("\nGreat password! No suggestions for improvement.")

            print("\n" + "=" * 40 + "\n")

        except KeyboardInterrupt:
            print("\n\nProgram interrupted. Exiting...")
            break
        except Exception as e:
            print(f"\nAn error occurred: {e}\n")

if __name__ == "__main__":
    test_password()
```

## Features of this program:

1. **Local evaluation only** - Passwords are never sent over the internet
2. **Multiple criteria** - Checks length, character variety, and common patterns
3. **Constructive feedback** - Provides specific suggestions for improvement
4. **No storage** - Passwords are not saved anywhere
5. **Interactive** - Allows testing multiple passwords in one session

## How to use:

1. Save the code to a file (e.g., `password_tester.py`)
2. Run it with Python: `python password_tester.py`
3. Enter a password when prompted (it will be hidden as you type)
